definition.script:
node('build-agent') {
  stage('build') {
    sh '''
source /etc/profile
mvn -B clean package
    '''
  }
  stage('image') {
    sh '''
      IMAGE=registry.example.com/library/demo-pipeline:${BUILD_ID}
      cat <<EOF > Dockerfile.tmp
      FROM registry.example.com/library/base-openjdk8:latest
      COPY app.jar /app.jar
EOF
      docker pull registry.example.com/library/base-openjdk8:latest
      docker build -f Dockerfile.tmp -t "$IMAGE" .
      docker push "$IMAGE"
    '''
  }
}
